// Function to find the maximum value in a vector of integers.
//
// Args:
//   numbers: A slice of i32 integers.
//
// Returns:
//   An Option containing the maximum value if the vector is not empty.
//   Returns None if the vector is empty.
fn find_max(numbers: &[i32]) -> Option<i32> {
    // Handle the case of an empty vector.
    if numbers.is_empty() {
        return None;
    }

    // Initialize the maximum value with the first element of the vector.
    let mut max_value = numbers[0];

    // Iterate over the remaining elements of the vector.
    for &number in &numbers[1..] {
        // If the current element is greater than the current maximum value,
        // update the maximum value.
        if number > max_value {
            max_value = number;
        }
    }

    // Return the maximum value wrapped in an Option.
    Some(max_value)
}

